import React, { useState } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                id: Date.now(),
                sender: loginUserId,
                text: message.trim(),
            };
            setMessages([...messages, newMessage]);
            setMessage('');

            // Save message to the server
            fetch('http://localhost:8080/api/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    headerId: chatId,
                    fromId: loginUserId,
                    toId: otherUserId,
                    content: message.trim(),
                }),
            })
                .then((response) => response.json())
                .then((data) => console.log(data))
                .catch((error) => console.error('Error:', error));
        }
    };

    return (
        <Container style={{ position: 'relative', height: '100vh', padding: '0' }}>
            <Button style={{ fontSize: '10px', margin: '10px' }} color="secondary" onClick={goBack}>
                뒤로가기
            </Button>
            <p style={{ marginLeft: '10px' }}>
                채팅방 ID: {chatId}, 상대방 ID: {otherUserId}, 내 ID: {loginUserId}
            </p>
            <div
                style={{
                    position: 'absolute',
                    top: '60px',
                    left: '0',
                    right: '0',
                    bottom: '60px',
                    overflowY: 'auto',
                    padding: '10px',
                }}
            >
                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        style={{
                            display: 'flex',
                            justifyContent: msg.sender === loginUserId ? 'flex-end' : 'flex-start',
                            marginBottom: '10px',
                        }}
                    >
                        <div
                            style={{
                                maxWidth: '60%',
                                padding: '10px',
                                borderRadius: '10px',
                                background: msg.sender === loginUserId ? '#007bff' : '#f1f0f0',
                                color: msg.sender === loginUserId ? '#fff' : '#000',
                                wordWrap: 'break-word',
                            }}
                        >
                            {msg.text}
                        </div>
                    </div>
                ))}
            </div>
            <div
                style={{
                    position: 'absolute',
                    bottom: '0',
                    left: '0',
                    width: '100%',
                    padding: '10px',
                    backgroundColor: '#fff',
                    borderTop: '1px solid #ccc',
                }}
            >
                <InputGroup>
                    <Input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        placeholder="메시지를 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSend}>
                            전송
                        </Button>
                    </InputGroupText>
                </InputGroup>
            </div>
        </Container>
    );
};

export default ChatRoom;
